        "name": "ui.py",
        "content": "\"\"\"\nAuto-generated LVGL UI Code for MicroPython\nProject: Clock\nGenerated: 2026-01-01T00:00:00.000Z\nPages: 1\n\nLVGL Version: 9.5 (PyDevices binding)\n\"\"\"\n\nimport lvgl as lv\n\nscreens = [None] * 1\ncurrent_screen = 0\nPAGE_CLOCK = 0\n\ndef clock_create_clock(parent=None):\n    global bg\n    if parent is None:\n        parent = lv.screen_active()\n\n    # panel: bg\n    bg = lv.obj(parent)\n    bg.set_pos(0, 0)\n    bg.set_size(480, 480)\n    bg.set_style_bg_color(lv.color_hex(0x0E1621), lv.PART.MAIN)\n    bg.set_style_border_width(0, lv.PART.MAIN)\n    bg.set_style_radius(0, lv.PART.MAIN)\n    bg.set_style_pad_all(0, lv.PART.MAIN)\n    bg.set_style_pad_gap(0, lv.PART.MAIN)\n    bg.set_scrollbar_mode(lv.SCROLLBAR_MODE.OFF)\n\n\ndef load_page(page_index):\n    global screens, current_screen\n\n    if page_index < 0 or page_index >= 1:\n        return\n\n    if screens[page_index] is None:\n        screens[page_index] = lv.obj()\n\n        if page_index == 0:\n            clock_create_clock(screens[0])\n\n    lv.screen_load(screens[page_index])\n    current_screen = page_index\n\ndef load_page_anim(page_index, anim, time_ms, delay_ms):\n    global screens, current_screen\n\n    if page_index < 0 or page_index >= 1:\n        return\n\n    if screens[page_index] is None:\n        screens[page_index] = lv.obj()\n\n        if page_index == 0:\n            clock_create_clock(screens[0])\n\n    lv.screen_load_anim(screens[page_index], anim, time_ms, delay_ms, False)\n    current_screen = page_index\n\ndef get_current_page():\n    return current_screen\n"
