        "name": "app_main.py",
        "content": "import sys\nimport display_driver\nimport lvgl as lv\nif (display_driver.WIDTH, display_driver.HEIGHT) != (480, 480):\n    raise RuntimeError('UI requires 480x480')\nAPP_DIR = __file__.rsplit('/', 1)[0] if '/' in __file__ else '.'\nif APP_DIR not in sys.path:\n    sys.path.insert(0, APP_DIR)\nimport ui\nimport app_events\n\nui.screens = [None] * 4\nui.screens[0] = lv.obj()\nui.fifteen_create_menu(ui.screens[0])\nui.screens[1] = lv.obj()\nui.fifteen_create_game(ui.screens[1])\nui.screens[2] = lv.obj()\nui.fifteen_create_options(ui.screens[2])\nui.screens[3] = lv.obj()\nui.fifteen_create_solved(ui.screens[3])\nui.screens[0].add_event_cb(app_events.menu_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.screens[1].add_event_cb(app_events.game_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.screens[3].add_event_cb(app_events.solved_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.btn_play.add_event_cb(app_events.btn_play_clicked, lv.EVENT.CLICKED, None)\nui.btn_again.add_event_cb(app_events.btn_again_clicked, lv.EVENT.CLICKED, None)\nui.btn_options.add_event_cb(app_events.btn_options_clicked, lv.EVENT.CLICKED, None)\nui.btn_back.add_event_cb(app_events.btn_back_clicked, lv.EVENT.CLICKED, None)\nui.btn_end_menu.add_event_cb(app_events.btn_end_menu_clicked, lv.EVENT.CLICKED, None)\nui.btn_quit.add_event_cb(app_events.btn_quit_clicked, lv.EVENT.CLICKED, None)\nui.opt_shuffle.add_event_cb(app_events.opt_shuffle_value_changed, lv.EVENT.VALUE_CHANGED, None)\nui.opt_sound.add_event_cb(app_events.opt_sound_value_changed, lv.EVENT.VALUE_CHANGED, None)\nui.tick = lv.timer_create(app_events.tick_tick, 33, None)\nui.tick.pause()\nlv.screen_load(ui.screens[0])\nui.current_screen = 0\ndisplay_driver.start()\nprint('LMS_APP_READY buffers=%s touch=%s' % (display_driver.BUFFERS, display_driver.indev is not None))\n"
