        "name": "lms_buzzer.py",
        "content": "# SPDX-License-Identifier: MIT\n# Copyright (c) 2026 Nunzio Raciti\nPIN = 1\n_pwm = None\n_timer = None\n\n\ndef tone(freq):\n    global _pwm\n    if freq <= 0:\n        off()\n        return\n    if _pwm is None:\n        from machine import PWM, Pin\n\n        _pwm = PWM(Pin(PIN), freq=int(freq), duty_u16=0)\n    _pwm.freq(int(freq))\n    _pwm.duty_u16(32768)\n\n\ndef off():\n    if _pwm is not None:\n        _pwm.duty_u16(0)\n\n\ndef _stop(timer):\n    off()\n    timer.pause()\n\n\ndef beep(freq, ms=40):\n    global _timer\n    import lvgl as lv\n\n    tone(freq)\n    if _timer is None:\n        _timer = lv.timer_create(_stop, ms, None)\n    else:\n        _timer.set_period(ms)\n        _timer.reset()\n        _timer.resume()\n"
