        "content": "import sys\nimport display_driver\nimport lvgl as lv\nif (display_driver.WIDTH, display_driver.HEIGHT) != (480, 480):\n    raise RuntimeError('UI requires 480x480')\nAPP_DIR = __file__.rsplit('/', 1)[0] if '/' in __file__ else '.'\nif APP_DIR not in sys.path:\n    sys.path.insert(0, APP_DIR)\nimport ui\nimport app_events\n\nui.screens = [None] * 1\nui.screens[0] = lv.obj()\nui.ftp_server_create_server(ui.screens[0])\nui.screens[0].add_event_cb(app_events.server_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.serve_switch.add_event_cb(app_events.serve_switch_value_changed, lv.EVENT.VALUE_CHANGED, None)\nui.new_password_button.add_event_cb(app_events.new_password_button_clicked, lv.EVENT.CLICKED, None)\nui.folder.add_event_cb(app_events.folder_value_changed, lv.EVENT.VALUE_CHANGED, None)\nui.tick = lv.timer_create(app_events.tick_tick, 20, None)\nlv.screen_load(ui.screens[0])\nui.current_screen = 0\ndisplay_driver.start()\nprint('LMS_APP_READY buffers=%s touch=%s' % (display_driver.BUFFERS, display_driver.indev is not None))\n"
