        "name": "ui.py",
        "content": "\"\"\"\nAuto-generated LVGL UI Code for MicroPython\nProject: Star Guard\nGenerated: 2026-01-01T00:00:00.000Z\nPages: 1\n\nLVGL Version: 9.5 (PyDevices binding)\n\"\"\"\n\nimport lvgl as lv\n\n# Fonts used: lv.font_montserrat_16, lv.font_montserrat_24 (font sizes are mapped to the ones available: 14, 16, 24)\n\n\nscreens = [None] * 1\ncurrent_screen = 0\nPAGE_MAIN = 0\n\n_styles = []\n\ndef _init_styles():\n    if _styles:\n        return\n    style = lv.style_t()\n    style.init()\n    style.set_bg_color(lv.color_hex(0x2E6FD8))\n    style.set_radius(10)\n    _styles.append(style)\n    style = lv.style_t()\n    style.init()\n    style.set_text_color(lv.color_hex(0xFFFFFF))\n    style.set_text_font(lv.font_montserrat_24)\n    _styles.append(style)\n\ndef star_guard_create_main(parent=None):\n    global bg, score, lives, field, message, btn_left, btn_fire, btn_right\n    if parent is None:\n        parent = lv.screen_active()\n    _init_styles()\n\n    # panel: bg\n    bg = lv.obj(parent)\n    bg.set_pos(0, 0)\n    bg.set_size(480, 480)\n    bg.set_style_bg_color(lv.color_hex(0x0B0D1A), lv.PART.MAIN)\n    bg.set_style_border_width(0, lv.PART.MAIN)\n    bg.set_style_radius(0, lv.PART.MAIN)\n    bg.set_style_pad_all(0, lv.PART.MAIN)\n    bg.set_style_pad_gap(0, lv.PART.MAIN)\n    bg.set_scrollbar_mode(lv.SCROLLBAR_MODE.OFF)\n\n    # label: score\n    score = lv.label(parent)\n    score.set_pos(8, 6)\n    score.set_size(190, 24)\n    score.set_text(\"Score 0\")\n    score.set_style_text_color(lv.color_hex(0xFFFFFF), lv.PART.MAIN)\n    score.set_style_text_font(lv.font_montserrat_16, lv.PART.MAIN)\n    score.set_style_text_align(lv.TEXT_ALIGN.LEFT, lv.PART.MAIN)\n\n    # label: lives\n    lives = lv.label(parent)\n    lives.set_pos(282, 6)\n    lives.set_size(190, 24)\n    lives.set_text(\"Wave 1   Lives 3\")\n    lives.set_style_text_color(lv.color_hex(0x9FE3B0), lv.PART.MAIN)\n    lives.set_style_text_font(lv.font_montserrat_16, lv.PART.MAIN)\n    lives.set_style_text_align(lv.TEXT_ALIGN.RIGHT, lv.PART.MAIN)\n\n    # panel: field\n    field = lv.obj(parent)\n    field.set_pos(0, 32)\n    field.set_size(480, 368)\n    field.set_style_bg_color(lv.color_hex(0x05060E), lv.PART.MAIN)\n    field.set_style_border_width(0, lv.PART.MAIN)\n    field.set_style_radius(0, lv.PART.MAIN)\n    field.set_style_pad_all(0, lv.PART.MAIN)\n    field.set_style_pad_gap(0, lv.PART.MAIN)\n    field.set_scrollbar_mode(lv.SCROLLBAR_MODE.OFF)\n\n    # label: message\n    message = lv.label(parent)\n    message.set_pos(90, 150)\n    message.set_size(300, 150)\n    message.set_text(\"STAR GUARD\\n\\nTap here to start\")\n    message.set_style_text_color(lv.color_hex(0xFFFFFF), lv.PART.MAIN)\n    message.set_style_text_font(lv.font_montserrat_24, lv.PART.MAIN)\n    message.set_style_text_align(lv.TEXT_ALIGN.CENTER, lv.PART.MAIN)\n\n    # button: btn_left\n    btn_left = lv.button(parent)\n    btn_left.set_pos(6, 406)\n    btn_left.set_size(146, 68)\n    btn_left.add_style(_styles[0], lv.PART.MAIN)\n    btn_left_label = lv.label(btn_left)\n    btn_left_label.set_text(\"Left\")\n    btn_left_label.center()\n    btn_left_label.add_style(_styles[1], lv.PART.MAIN)\n\n    # button: btn_fire\n    btn_fire = lv.button(parent)\n    btn_fire.set_pos(167, 406)\n    btn_fire.set_size(146, 68)\n    btn_fire.set_style_bg_color(lv.color_hex(0xC0503A), lv.PART.MAIN)\n    btn_fire.set_style_radius(10, lv.PART.MAIN)\n    btn_fire_label = lv.label(btn_fire)\n    btn_fire_label.set_text(\"Fire\")\n    btn_fire_label.center()\n    btn_fire_label.add_style(_styles[1], lv.PART.MAIN)\n\n    # button: btn_right\n    btn_right = lv.button(parent)\n    btn_right.set_pos(328, 406)\n    btn_right.set_size(146, 68)\n    btn_right.add_style(_styles[0], lv.PART.MAIN)\n    btn_right_label = lv.label(btn_right)\n    btn_right_label.set_text(\"Right\")\n    btn_right_label.center()\n    btn_right_label.add_style(_styles[1], lv.PART.MAIN)\n\n\ndef load_page(page_index):\n    global screens, current_screen\n\n    if page_index < 0 or page_index >= 1:\n        return\n\n    if screens[page_index] is None:\n        screens[page_index] = lv.obj()\n\n        if page_index == 0:\n            star_guard_create_main(screens[0])\n\n    lv.screen_load(screens[page_index])\n    current_screen = page_index\n\ndef load_page_anim(page_index, anim, time_ms, delay_ms):\n    global screens, current_screen\n\n    if page_index < 0 or page_index >= 1:\n        return\n\n    if screens[page_index] is None:\n        screens[page_index] = lv.obj()\n\n        if page_index == 0:\n            star_guard_create_main(screens[0])\n\n    lv.screen_load_anim(screens[page_index], anim, time_ms, delay_ms, False)\n    current_screen = page_index\n\ndef get_current_page():\n    return current_screen\nimport lms_buzzer as buzzer\n"
