        "content": "import sys\nimport display_driver\nimport lvgl as lv\nif (display_driver.WIDTH, display_driver.HEIGHT) != (480, 480):\n    raise RuntimeError('UI requires 480x480')\nAPP_DIR = __file__.rsplit('/', 1)[0] if '/' in __file__ else '.'\nif APP_DIR not in sys.path:\n    sys.path.insert(0, APP_DIR)\nimport ui\nimport app_events\n\nui.screens = [None] * 2\nui.screens[0] = lv.obj()\nui.weather_create_main(ui.screens[0])\nui.screens[1] = lv.obj()\nui.weather_create_settings(ui.screens[1])\nui.screens[0].add_event_cb(app_events.main_screen_loaded, lv.EVENT.SCREEN_LOADED, None)\nui.refresh.add_event_cb(app_events.refresh_clicked, lv.EVENT.CLICKED, None)\nui.settings_button.add_event_cb(app_events.settings_button_clicked, lv.EVENT.CLICKED, None)\nui.back.add_event_cb(app_events.back_clicked, lv.EVENT.CLICKED, None)\nui.units.add_event_cb(app_events.units_value_changed, lv.EVENT.VALUE_CHANGED, None)\nui.clock = lv.timer_create(app_events.clock_tick, 1000, None)\nlv.screen_load(ui.screens[0])\nui.current_screen = 0\ndisplay_driver.start()\nprint('LMS_APP_READY buffers=%s touch=%s' % (display_driver.BUFFERS, display_driver.indev is not None))\n"
